templates.template:
.wrxtFreshness {
    width: min(100%, 310px);
    margin: 6px 0 10px auto;
    position: relative;
    z-index: 2;

    > .block-container {
        border-radius: 6px;
        overflow: visible;
        box-shadow: none;
    }
}

.wrxtFreshness-main { padding: 8px 10px; }
.wrxtFreshness-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.wrxtFreshness-heading { display: flex; align-items: center; gap: 6px; min-width: 0; }
.wrxtFreshness-title { font-size: 13px; line-height: 1.2; white-space: nowrap; }
.wrxtFreshness-heading .label { font-size: 10px; line-height: 1.25; padding: 2px 5px; }
.wrxtFreshness-icons { display: flex; align-items: center; gap: 4px; flex: 0 0 auto; }

.wrxtFreshness-pop { position: relative; margin: 0; }
.wrxtFreshness-pop > summary {
    list-style: none;
    width: 22px;
    height: 22px;
    border: 1px solid @xf-borderColor;
    border-radius: 50%;
    display: grid;
    place-items: center;
    cursor: pointer;
    color: @xf-textColorMuted;
    font-size: 11px;
    line-height: 1;
    user-select: none;
}
.wrxtFreshness-pop > summary::-webkit-details-marker { display: none; }
.wrxtFreshness-actions > summary { width: 28px; border-radius: 11px; letter-spacing: 1px; }
.wrxtFreshness-popBody {
    position: absolute;
    right: 0;
    top: calc(100% + 6px);
    width: 260px;
    padding: 10px;
    border: 1px solid @xf-borderColor;
    border-radius: 6px;
    background: @xf-contentBg;
    box-shadow: 0 5px 18px rgba(0, 0, 0, .22);
    z-index: 20;
    font-size: 12px;
}
.wrxtFreshness-popBody p { margin: 5px 0 0; color: @xf-textColorMuted; line-height: 1.35; }
.wrxtFreshness-popBody--actions { display: grid; gap: 8px; }
.wrxtFreshness-popBody--actions form { margin: 0; }
.wrxtFreshness-actionForm { display: flex; gap: 5px; align-items: center; }
.wrxtFreshness-actionForm .input, .wrxtFreshness-actionForm select { min-width: 0; font-size: 12px; }
.wrxtFreshness-actionForm .button { white-space: nowrap; }

.wrxtFreshness-meta {
    display: flex;
    gap: 9px;
    align-items: center;
    flex-wrap: wrap;
    margin-top: 5px;
    color: @xf-textColorMuted;
    font-size: 11px;
    line-height: 1.3;
}
.wrxtFreshness-ownerBadge { color: @xf-textColorFeature; }
.wrxtFreshness-replacement { margin-top: 5px; font-size: 11px; }

.wrxtFreshness-voteForm { margin-top: 7px; }
.wrxtFreshness-voteButtons { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.wrxtFreshness-voteButtons .button { padding: 4px 7px; min-height: 28px; font-size: 11px; }

.wrxtFreshness-more { margin-top: 5px; font-size: 11px; }
.wrxtFreshness-more > summary { cursor: pointer; color: @xf-textColorMuted; }
.wrxtFreshness-fields, .wrxtFreshness-resultsBody { display: grid; gap: 7px; margin-top: 7px; }
.wrxtFreshness-fields label { display: grid; gap: 3px; }
.wrxtFreshness-fields label > span { color: @xf-textColorMuted; }
.wrxtFreshness-fields .input, .wrxtFreshness-fields select { width: 100%; font-size: 12px; }
.wrxtFreshness-main--waiting { padding-top: 7px; padding-bottom: 7px; }

@media (max-width: @xf-responsiveMedium) {
    .wrxtFreshness {
        width: 100%;
        margin: 7px 0 10px;
    }
    .wrxtFreshness-main { padding: 8px 9px; }
    .wrxtFreshness-popBody { position: fixed; left: 12px; right: 12px; top: auto; width: auto; }
}

/* v1.0.5 clearer interactive controls */
.wrxtFreshness {
    width: 340px;
    max-width: 100%;
}

.wrxtFreshness > .block-container {
    border: 1px solid @xf-borderColor;
    border-radius: 8px;
    background: @xf-contentBg;
    box-shadow: 0 2px 8px rgba(0, 0, 0, .12);
    overflow: visible;
}

.wrxtFreshness-main {
    padding: 9px 10px;
}

.wrxtFreshness-top {
    gap: 8px;
    align-items: center;
}

.wrxtFreshness-heading {
    flex: 1 1 auto;
    flex-wrap: wrap;
    row-gap: 4px;
}

.wrxtFreshness-title {
    font-size: 13px;
    font-weight: 700;
    letter-spacing: .01em;
}

.wrxtFreshness-heading .label {
    display: inline-flex;
    align-items: center;
    min-height: 20px;
    padding: 2px 7px;
    border: 1px solid @xf-borderColor;
    border-radius: 999px;
    background: rgba(127, 127, 127, .10);
    color: @xf-textColor;
    font-size: 10px;
    font-weight: 600;
    line-height: 1.2;
}

.wrxtFreshness-icons {
    display: flex;
    align-items: center;
    gap: 5px;
}

.wrxtFreshness-pop > summary {
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    list-style: none !important;
    min-width: 54px;
    height: 28px;
    margin: 0;
    padding: 0 8px;
    border: 1px solid @xf-borderColor;
    border-radius: 7px;
    background: rgba(127, 127, 127, .10);
    color: @xf-linkColor;
    cursor: pointer;
    font-size: 0;
    font-weight: 700;
    line-height: 1;
    box-shadow: 0 1px 2px rgba(0, 0, 0, .10);
    transition: background .15s ease, border-color .15s ease, color .15s ease, transform .15s ease, box-shadow .15s ease;
}

.wrxtFreshness-pop > summary::marker {
    content: '';
    font-size: 0;
}

.wrxtFreshness-pop > summary::-webkit-details-marker {
    display: none;
}

.wrxtFreshness-help > summary::before {
    content: '?';
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 16px;
    height: 16px;
    margin-right: 5px;
    border: 1px solid currentColor;
    border-radius: 50%;
    font-size: 10px;
    line-height: 1;
}

.wrxtFreshness-help > summary::after {
    content: 'Bilgi';
    font-size: 11px;
    line-height: 1;
}

.wrxtFreshness-actions > summary {
    min-width: 72px;
}

.wrxtFreshness-actions > summary::before {
    content: '•••';
    margin-right: 5px;
    font-size: 11px;
    letter-spacing: 1px;
    line-height: 1;
}

.wrxtFreshness-actions > summary::after {
    content: 'İşlemler';
    font-size: 11px;
    line-height: 1;
}

.wrxtFreshness-pop > summary:hover,
.wrxtFreshness-pop > summary:focus-visible {
    background: rgba(127, 127, 127, .18);
    border-color: @xf-linkColor;
    outline: none;
    transform: translateY(-1px);
    box-shadow: 0 2px 5px rgba(0, 0, 0, .16);
}

.wrxtFreshness-pop[open] > summary {
    background: @xf-linkColor;
    border-color: @xf-linkColor;
    color: @xf-contentBg;
    transform: none;
}

.wrxtFreshness-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
    margin-top: 7px;
    color: @xf-textColorMuted;
    font-size: 11px;
}

.wrxtFreshness-meta > span {
    display: inline-flex;
    align-items: center;
    min-height: 22px;
    padding: 2px 7px;
    border: 1px solid @xf-borderColor;
    border-radius: 999px;
    background: rgba(127, 127, 127, .08);
    line-height: 1.2;
}

.wrxtFreshness-meta > span b {
    color: @xf-textColor;
}

.wrxtFreshness-ownerBadge {
    color: @xf-textColor;
    font-weight: 600;
}

.wrxtFreshness-voteButtons {
    gap: 6px;
}

.wrxtFreshness-voteButtons .button {
    min-height: 32px;
    padding: 5px 9px;
    border-radius: 7px;
    font-size: 11px;
    font-weight: 600;
    box-shadow: 0 1px 2px rgba(0, 0, 0, .10);
    transition: transform .15s ease, box-shadow .15s ease;
}

.wrxtFreshness-voteButtons .button:hover {
    transform: translateY(-1px);
    box-shadow: 0 2px 5px rgba(0, 0, 0, .16);
}

.wrxtFreshness-more > summary {
    display: inline-flex;
    align-items: center;
    min-height: 24px;
    margin-top: 2px;
    padding: 2px 7px;
    border: 1px solid transparent;
    border-radius: 6px;
    cursor: pointer;
}

.wrxtFreshness-more > summary:hover {
    border-color: @xf-borderColor;
    background: rgba(127, 127, 127, .08);
    color: @xf-textColor;
}

@media (max-width: 650px) {
    .wrxtFreshness {
        width: 100%;
        max-width: none;
        margin-left: 0;
        margin-right: 0;
    }

    .wrxtFreshness-pop > summary {
        height: 32px;
    }
}
